    # rendered uniformly.  Determine its representative by the most frequent
    # non-divider entry (with zero treated as background).
    h,w=len(g),len(g[0]); out=[r[:] for r in g]
    for r0 in range(0,h,4):
      for c0 in range(0,w,4):
