        vals=[g[r][c] for r in range(r0,r0+3) for c in range(c0,c0+3) if g[r][c]!=5]
        if not vals: continue
        cnt={x:vals.count(x) for x in set(vals)}
        # prefer positive values; ties use the largest (the convention in the examples)
        m=max(cnt.values()); z=max(x for x in cnt if cnt[x]==m)
        for r in range(r0,r0+3):
          for c in range(c0,c0+3): out[r][c]=z
    return out"}

